// RevenueCat SDK error codes (PurchasesErrorCode), one page each at /errors/<slug>. Writing rules: apps/site/CONTENT.md.
// Numbers and names come from the SDK source (MIT): purchases-ios Sources/Generated/ErrorCode.swift and Sources/Error Handling/,
// purchases-android PurchasesErrorCode.kt and common/errors.kt, and the Flutter and React Native enums. Checked 2026-10-01.
// Apple and Google facts link the documentation page they come from. RevenueDot behavior comes from apps/server/src.
// `android` is "n/a" where the Android SDK source has no member for the code; the page text then names the nearest Android code.
import type { Faq } from "../site";
import type { ErrorPage } from "./types";

/** The FAQ every page carries: how to check the code in the two hybrid SDKs. `rn` is null where the React Native enum has no member. */
const hy = (name: string, rn: string | null, flutter: string, num: number, note = ""): Faq => ({
  q: `How do I check for ${name} in React Native and Flutter?`,
  a: (rn
    ? `In React Native, compare \`error.code\` with \`PURCHASES_ERROR_CODE.${rn}\`. `
    : `The React Native \`PURCHASES_ERROR_CODE\` enum in the SDK source has no member for it, so compare \`error.code\` with the string \`"${num}"\`. `)
    + `In Flutter, convert the \`PlatformException\` with \`PurchasesErrorHelper.getErrorCode(e)\` and compare the result with \`PurchasesErrorCode.${flutter}\`.${note ? " " + note : ""}`,
});

